-- =============================================================
-- 03: Mongo FK 設定の最終データ投入
--   現在の運用状態を基準に並び順と ID を整理した完全版
-- =============================================================

TRUNCATE TABLE fk_mongo_migration_config RESTART IDENTITY;



SELECT setval('fk_mongo_migration_config_id_seq', COALESCE((SELECT MAX(id) FROM fk_mongo_migration_config), 1), true);

